replace_once('src/boss-catalog.js',"function fireFan(e,count,spread,speed,damage,color,r=5.5){const base=Math.atan2(player.y-e.y,player.x-e.x),visual=enemyProjectileVisualFor(e,'fan');for(let i=0;i<count;i++)spawnEnemyProjectile(e.x,e.y,base+(i-(count-1)/2)*spread,speed,damage,color,r,6,visual);}","function fireFan(e,count,spread,speed,damage,color,r=5.5){const shots=e.firstBoss?Math.max(3,Math.ceil(count*.72)):count,shotSpeed=e.firstBoss?speed*.90:speed,shotDamage=e.firstBoss?damage*.88:damage,base=Math.atan2(player.y-e.y,player.x-e.x),visual=enemyProjectileVisualFor(e,'fan');for(let i=0;i<shots;i++)spawnEnemyProjectile(e.x,e.y,base+(i-(shots-1)/2)*spread,shotSpeed,shotDamage,color,r,6,visual);}",'first boss fan density')
