replace_once('src/boss-catalog.js',"function summonMinions(e,count=4,kind='grunt'){for(let i=0;i<count;i++){const m=spawnEnemy('normal');if(!m)continue;m.type=kind;m.x=e.x+Math.cos(i/count*TAU)*rand(100,170);m.y=e.y+Math.sin(i/count*TAU)*rand(100,170);m.hp*=1.18;m.maxHp=m.hp;m.damage*=1.06;m.color=e.color;m.eventKind=e.eventKind==='void'?'void-minion':m.eventKind;}}","function summonMinions(e,count=4,kind='grunt'){const actual=e.firstBoss?Math.min(1,count):count;for(let i=0;i<actual;i++){const m=spawnEnemy('normal');if(!m)continue;m.type=kind;m.x=e.x+Math.cos(i/Math.max(1,actual)*TAU)*rand(100,170);m.y=e.y+Math.sin(i/Math.max(1,actual)*TAU)*rand(100,170);m.hp*=e.firstBoss?.97:1.18;m.maxHp=m.hp;m.damage*=e.firstBoss?.82:1.06;m.color=e.color;m.eventKind=e.eventKind==='void'?'void-minion':m.eventKind;}}",'first boss summons')
